     * `providerStop` 时 `<error>` 块由文案表铸造（原因 → 动作 → 事实行 → 原文行），而不是
     * 只贴一句 provider 原文——主代理读完必须知道该做什么。
     */
    failure?: DynamicWorkflowRunError;
    stderrFile?: string;
    stdoutFile?: string;
    subagentType?: string;
    summary: string;
    taskId: string;
    taskType: RuntimeTaskType;
    toolUseId?: string;
    usage?: {
        durationMs?: number;
        modelUsage?: ModelUsage;
        toolUseCount?: number;
        totalTokens?: number;
    };
}
